"""Core values used by the incident operations application."""

from __future__ import annotations

from dataclasses import dataclass, replace
from enum import StrEnum


class Severity(StrEnum):
    P1 = "P1"
    P2 = "P2"
    P3 = "P3"
    P4 = "P4"


class IncidentStatus(StrEnum):
    OPEN = "open"
    ACKNOWLEDGED = "acknowledged"
    RESOLVED = "resolved"


SLA_SECONDS: dict[Severity, int] = {
    Severity.P1: 60,
    Severity.P2: 300,
    Severity.P3: 900,
    Severity.P4: 3600,
}

VALID_TRANSITIONS: frozenset[tuple[IncidentStatus, IncidentStatus]] = frozenset(
    {
        (IncidentStatus.OPEN, IncidentStatus.ACKNOWLEDGED),
        (IncidentStatus.OPEN, IncidentStatus.RESOLVED),
        (IncidentStatus.ACKNOWLEDGED, IncidentStatus.RESOLVED),
    }
)


@dataclass(frozen=True, slots=True)
class Incident:
    id: str
    fingerprint: str
    title: str
    severity: Severity
    status: IncidentStatus
    owner: str | None
    alert_count: int
    version: int
    escalation_level: int
    created_at: float
    updated_at: float
    sla_deadline: float

    def changed(self, **values: object) -> "Incident":
        return replace(self, **values)


@dataclass(frozen=True, slots=True)
class AuditEvent:
    id: int
    incident_id: str
    type: str
    timestamp: float
    details: dict


class IncidentNotFound(Exception):
    def __init__(self, incident_id: str) -> None:
        super().__init__(f"incident not found: {incident_id}")
        self.incident_id = incident_id


class VersionConflict(Exception):
    def __init__(self, incident_id: str, expected: int, actual: int) -> None:
        super().__init__(
            f"version conflict for {incident_id}: expected {expected}, actual {actual}"
        )
        self.incident_id = incident_id
        self.expected = expected
        self.actual = actual


class InvalidTransition(Exception):
    def __init__(self, current: str, target: str) -> None:
        super().__init__(f"invalid status transition: {current} -> {target}")
        self.current = current
        self.target = target

