:root {
  color: #172033;
  background: #eef2f7;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
}

* { box-sizing: border-box; }

body { margin: 0; }

#app {
  max-width: 960px;
  margin: 0 auto;
  padding: 16px;
  overflow-x: hidden;
}

.app-header, .filters, .incident-list, .incident-detail, .summary {
  background: white;
  border: 1px solid #d8e0ea;
  border-radius: 12px;
  padding: 16px;
}

.app-header { margin-bottom: 12px; }

.eyebrow {
  color: #3154a5;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  margin: 0;
}

h1, h2 { margin-top: 0; margin-bottom: 8px; }
p { margin: 0; }

.summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
  padding: 12px;
}

.summary .stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 64px;
  padding: 6px 10px;
  border-radius: 8px;
  background: #f4f7fb;
}

.summary .stat .num { font-size: 20px; font-weight: 800; }
.summary .stat .label { font-size: 11px; color: #5a6a82; text-transform: uppercase; }

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: end;
  margin-bottom: 12px;
}

.filter-label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: #5a6a82;
}

input, select, button {
  box-sizing: border-box;
  min-height: 38px;
  padding: 6px 8px;
  font: inherit;
  border: 1px solid #c4cdda;
  border-radius: 6px;
}

button {
  border: 0;
  border-radius: 8px;
  color: white;
  background: #3154a5;
  font-weight: 700;
  cursor: pointer;
}

button:hover { background: #28468f; }

.btn-secondary { background: #5a6a82; }
.btn-secondary:hover { background: #475571; }

.btn-ack { background: #c97a1e; }
.btn-ack:hover { background: #b06d1a; }

.btn-resolve { background: #1e8a4a; }
.btn-resolve:hover { background: #197640; }

button:disabled { opacity: .45; cursor: not-allowed; }

.feedback { min-height: 20px; margin: 8px 0; font-size: 14px; }
.feedback.error { color: #c0392b; }
.feedback.success { color: #1e8a4a; }

.board {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.incident-list { display: flex; flex-direction: column; gap: 6px; max-height: 560px; overflow-y: auto; }

.incident-row {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 10px;
  cursor: pointer;
  transition: border-color .15s;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 8px;
  align-items: start;
}

.incident-row:hover { border-color: #3154a5; }
.incident-row.selected { border-color: #3154a5; background: #f4f7fb; }

.sev-badge {
  display: inline-block;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
  color: white;
}

.sev-P1 { background: #c0392b; }
.sev-P2 { background: #e67e22; }
.sev-P3 { background: #f39c12; color: #172033; }
.sev-P4 { background: #7f8c8d; }

.status-badge {
  display: inline-block;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
}

.status-open { background: #fee; color: #c0392b; }
.status-acknowledged { background: #fef9e7; color: #b06d1a; }
.status-resolved { background: #e8f8f0; color: #1e8a4a; }

.incident-detail { min-height: 200px; }

.detail-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin-bottom: 12px;
  font-size: 14px;
}

.detail-grid dt { color: #5a6a82; font-weight: 600; }
.detail-grid dd { margin: 0; }

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: end;
  margin-bottom: 12px;
}

.controls label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: #5a6a82;
  flex: 1;
}

.timeline {
  border-left: 2px solid #d8e0ea;
  padding-left: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.timeline-item {
  font-size: 13px;
  position: relative;
}

.timeline-item::before {
  content: '';
  position: absolute;
  left: -16px;
  top: 4px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #3154a5;
}

.timeline-item .ev-type { font-weight: 700; }
.timeline-item .ev-time { color: #8395ad; font-size: 11px; }
.timeline-item .ev-details { color: #5a6a82; word-break: break-word; }

.placeholder { color: #8395ad; }

@media (max-width: 600px) {
  .board { grid-template-columns: 1fr; }
  .filters { flex-direction: column; align-items: stretch; }
  .incident-list { max-height: 320px; }
}

