(function () {
  "use strict";

  var state = {
    incidents: [],
    selectedId: null,
    selectedDetail: null,
    statusFilter: "",
    severityFilter: "",
    feedback: "",
  };

  var els = {};

  function setFeedback(msg, kind) {
    state.feedback = msg || "";
    if (els.feedback) {
      els.feedback.textContent = msg || "";
      els.feedback.className = "feedback" + (kind ? " " + kind : "");
    }
  }

  function api(path, method, body) {
    var opts = { method: method || "GET", headers: {} };
    if (body !== undefined) {
      opts.headers["Content-Type"] = "application/json";
      opts.body = JSON.stringify(body);
    }
    return fetch(path, opts).then(function (r) {
      if (r.status === 204) return null;
      return r.json().then(function (data) {
        if (!r.ok) {
          var err = new Error((data && data.error) || ("HTTP " + r.status));
          err.status = r.status;
          err.body = data;
          throw err;
        }
        return data;
      });
    });
  }

  function buildSummary(summary) {
    var html = '';
    html += '<div class="stat"><span class="num">' + (summary.total || 0) + '</span><span class="label">Total</span></div>';
    var statuses = ["open", "acknowledged", "resolved"];
    for (var i = 0; i < statuses.length; i++) {
      var s = statuses[i];
      html += '<div class="stat"><span class="num">' + ((summary.by_status || {})[s] || 0) + '</span><span class="label">' + s + '</span></div>';
    }
    var sevs = ["P1", "P2", "P3", "P4"];
    for (var j = 0; j < sevs.length; j++) {
      var sv = sevs[j];
      html += '<div class="stat"><span class="num">' + ((summary.by_severity || {})[sv] || 0) + '</span><span class="label">' + sv + '</span></div>';
    }
    els.summary.innerHTML = html;
  }

  function renderIncidentRow(incident) {
    var div = document.createElement("div");
    div.setAttribute("data-testid", "incident-row");
    div.className = "incident-row" + (incident.id === state.selectedId ? " selected" : "");
    div.dataset.id = incident.id;
    div.innerHTML =
      '<span class="sev-badge sev-' + incident.severity + '">' + incident.severity + '</span>' +
      '<div>' +
        '<div style="font-weight:600">' + esc(incident.title) + '</div>' +
        '<div style="font-size:12px;color:#5a6a82">' +
          '<span class="status-badge status-' + incident.status + '">' + incident.status + '</span>' +
          (incident.owner ? ' &middot; ' + esc(incident.owner) : '') +
          ' &middot; alerts: ' + incident.alert_count +
          ' &middot; v' + incident.version +
        '</div>' +
      '</div>';
    div.addEventListener("click", function () { selectIncident(incident.id); });
    return div;
  }

  function renderList() {
    els.list.innerHTML = "";
    if (state.incidents.length === 0) {
      els.list.innerHTML = '<p class="placeholder">No incidents match the current filters.</p>';
      return;
    }
    var frag = document.createDocumentFragment();
    for (var i = 0; i < state.incidents.length; i++) {
      frag.appendChild(renderIncidentRow(state.incidents[i]));
    }
    els.list.appendChild(frag);
  }

  function esc(text) {
    var d = document.createElement("div");
    d.textContent = text == null ? "" : String(text);
    return d.innerHTML;
  }

  function formatTs(ts) {
    if (!ts) return "—";
