    html += '<dt>Updated</dt><dd>' + formatTs(d.updated_at) + '</dd>';
    html += '<dt>SLA deadline</dt><dd>' + formatTs(d.sla_deadline) + '</dd>';
    html += '</dl>';
    html += '<div class="controls">';
    html += '<label>Owner <input data-testid="owner-input" id="owner-input" type="text" value="' + esc(d.owner || "") + '" placeholder="Assign owner"></label>';
    html += '<button data-testid="acknowledge-action" id="ack-action" class="btn-ack"' + (canAck ? '' : ' disabled') + '>Acknowledge</button>';
    html += '<button data-testid="resolve-action" id="resolve-action" class="btn-resolve"' + (canResolve ? '' : ' disabled') + '>Resolve</button>';
    html += '</div>';
    html += '<h3>Audit timeline</h3>';
    html += '<div data-testid="timeline" class="timeline">';
    var events = d.events || [];
    if (events.length === 0) {
      html += '<p class="placeholder">No audit events.</p>';
    } else {
      for (var i = 0; i < events.length; i++) {
        var ev = events[i];
        html += '<div class="timeline-item">';
        html += '<div><span class="ev-type">' + esc(ev.type) + '</span> <span class="ev-time">' + formatTs(ev.timestamp) + '</span></div>';
        html += '<div class="ev-details">' + esc(JSON.stringify(ev.details)) + '</div>';
        html += '</div>';
      }
    }
    html += '</div>';
    els.detail.innerHTML = html;

    var ackBtn = document.getElementById("ack-action");
    if (ackBtn) ackBtn.addEventListener("click", function () { doUpdate(d.id, d.version, null, "acknowledged"); });
    var resolveBtn = document.getElementById("resolve-action");
    if (resolveBtn) resolveBtn.addEventListener("click", function () { doUpdate(d.id, d.version, null, "resolved"); });
  }

  function selectIncident(id) {
    state.selectedId = id;
    api("/api/incidents/" + encodeURIComponent(id)).then(function (detail) {
      state.selectedDetail = detail;
      renderList();
      renderDetail();
    }).catch(function (err) {
      setFeedback("Failed to load incident: " + err.message, "error");
    });
  }

  function doUpdate(id, version, owner, status) {
    var payload = { expected_version: version };
    if (owner !== null) payload.owner = owner;
    if (status) payload.status = status;
    api("/api/incidents/" + encodeURIComponent(id), "PATCH", payload).then(function (updated) {
      setFeedback("Incident updated", "success");
      state.selectedDetail = updated;
      return refresh();
    }).catch(function (err) {
      if (err.status === 409) {
        setFeedback("Version conflict: another operator updated this incident. Refreshing.", "error");
      } else {
        setFeedback("Update failed: " + err.message, "error");
      }
      selectIncident(id);
    });
  }

  function refresh() {
    var qs = [];
    if (state.statusFilter) qs.push("status=" + encodeURIComponent(state.statusFilter));
    if (state.severityFilter) qs.push("severity=" + encodeURIComponent(state.severityFilter));
    var path = "/api/incidents" + (qs.length ? "?" + qs.join("&") : "");
    var p1 = api(path).then(function (data) { state.incidents = data || []; renderList(); });
    var p2 = api("/api/summary").then(buildSummary);
    return Promise.all([p1, p2]).catch(function (err) {
      setFeedback("Failed to refresh: " + err.message, "error");
    });
  }

  function runEscalation() {
    api("/api/escalations/run", "POST", {}).then(function (result) {
      if (result) {
        setFeedback("Escalated incident " + result.id + " to level " + result.escalation_level, "success");
      } else {
        setFeedback("No due escalations", "success");
      }
      return refresh();
    }).catch(function (err) {
      setFeedback("Escalation failed: " + err.message, "error");
    });
  }

  function getState() {
    return {
      statusFilter: state.statusFilter,
      severityFilter: state.severityFilter,
      selectedIncidentId: state.selectedId,
      incidents: state.incidents,
      feedback: state.feedback,
    };
  }

  function init() {
    els.app = document.getElementById("app");
    els.summary = document.getElementById("summary");
    els.list = document.getElementById("incident-list");
    els.detail = document.getElementById("incident-detail");
    els.feedback = document.getElementById("feedback");
    els.statusFilter = document.getElementById("status-filter");
    els.severityFilter = document.getElementById("severity-filter");
    els.escalateBtn = document.getElementById("escalate-btn");

    els.statusFilter.addEventListener("change", function () {
      state.statusFilter = els.statusFilter.value;
      refresh();
    });
    els.severityFilter.addEventListener("change", function () {
      state.severityFilter = els.severityFilter.value;
      refresh();
    });
    els.escalateBtn.addEventListener("click", runEscalation);

    els.detail.addEventListener("change", function (e) {
      if (e.target && e.target.id === "owner-input") {
        // track but don't submit until an action
      }
    });
    els.detail.addEventListener("click", function (e) {
      var target = e.target;
      if (!target) return;
      if (target.id === "ack-action" || target.id === "resolve-action") return;
    });

    // expose owner change via a custom approach: pressing Enter in owner field assigns
    els.detail.addEventListener("keydown", function (e) {
      if (e.key === "Enter" && e.target && e.target.id === "owner-input") {
        e.preventDefault();
        var d = state.selectedDetail;
        if (d) doUpdate(d.id, d.version, e.target.value, null);
      }
    });

    window.incidentOps = {
      refresh: refresh,
      selectIncident: selectIncident,
      getState: getState,
    };

    refresh();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
